        self._skills: Dict[str, SkillDescriptor] = {}

    def register(self, name: str, domain: str, description: str, input_schema: Dict[str, str], clearance: int = 5):
        def decorator(func: Callable[..., Any]):
            self._skills[name] = SkillDescriptor(
                name=name, domain=domain, description=description,
                input_schema=input_schema, handler=func, security_clearance=clearance
            )
            return func
        return decorator

    def execute(self, name: str, agent_clearance: int, **kwargs) -> Any:
