    def __init__(self, dim: int = 32, subvectors: int = 4, centroids_per_sub: int = 8):
        self.dim = dim
        self.M = subvectors
        self.sub_dim = dim // subvectors
        self.K = centroids_per_sub
        self.codebooks = np.zeros((self.M, self.K, self.sub_dim))
        self.codes: List[np.ndarray] = []
        self.doc_ids: List[str] = []

    def fit_and_index(self, vectors: np.ndarray, ids: List[str]):
        rng = np.random.default_rng(42)
