    def index_python_source(source_code: str) -> Dict[str, Any]:
        tree = ast.parse(source_code)
        symbols = []
        merkle_leaves = []
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                node_src = ast.unparse(node)
